"""Self-contained local reports. No external scripts, fonts, images, or API calls."""
import json
from pathlib import Path

STYLE='''
:root{font:15px/1.7 "Microsoft YaHei",sans-serif;color:#243142;background:#f3f5f8}*{box-sizing:border-box}body{margin:0}header{padding:28px max(24px,calc((100vw - 1180px)/2));background:#24364b;color:white}h1{margin:0;font-size:27px}h2{font-size:20px}main{max-width:1180px;margin:24px auto;padding:0 18px}.notice{background:#fff4dd;border-left:4px solid #bf831a;padding:12px 16px;margin:14px 0}.panel,.card{background:white;border:1px solid #dce2e9;border-radius:12px;padding:20px;margin:16px 0}input,select,textarea,button{font:inherit;padding:9px 12px;border:1px solid #b7c2d0;border-radius:6px}input[type=search]{min-width:310px}button{background:#285f64;color:white;cursor:pointer}button.secondary{background:white;color:#285f64}button:disabled{opacity:.5;cursor:default}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.pill{display:inline-block;background:#edf2f7;border-radius:20px;padding:2px 10px;margin:3px;font-size:13px}.risk{color:#a44631}.muted{color:#626e7c;font-size:13px}pre,textarea{white-space:pre-wrap;word-break:break-word;width:100%;background:#f7f9fc}pre{padding:12px;border-radius:6px}textarea{min-height:260px;font:13px/1.6 Consolas,"Microsoft YaHei",monospace}summary{cursor:pointer;font-weight:bold}details{margin:10px 0}a{color:#1e6267}.cols{display:grid;grid-template-columns:1fr 1fr;gap:18px}#pager{display:flex;justify-content:center;gap:16px;margin:22px}.success{color:#246749}.error{color:#ad352d}.hidden{display:none}@media(max-width:760px){.cols{grid-template-columns:1fr}input[type=search]{min-width:0;width:100%}header{padding:22px}main{margin:12px auto}}
'''

def html(title,data,body,script):
    payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
    subtitle='对照原文，记录有依据的评价' if '标注' in title else '按你的需求挑款，优缺点一起看'
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+'</title><style>'+STYLE+'</style><header><h1>'+title+'</h1><div>'+subtitle+'</div></header><main>'+body+'</main><script id="data" type="application/json">'+payload+'</script><script>'+HELPERS+script+'</script></html>'

HELPERS=r'''
const DATA=JSON.parse(document.getElementById('data').textContent);
function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined&&text!==null)x.textContent=text;if(cls)x.className=cls;return x;}
function add(parent,tag,text,cls){const x=el(tag,text,cls);parent.append(x);return x;}
function detail(parent,title,text){const d=add(parent,'details');add(d,'summary',title);add(d,'pre',text);return d;}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/x-ndjson;charset=utf-8'}));const a=el('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
'''

VIEW_BODY='''
<div class="notice" id="priceNotice"></div>
<section class="panel"><h2>你想买什么样的衣服？</h2><p class="muted">先选一个需求，看看我会怎样帮你挑。你也可以用文件夹里的“启动推荐问答.cmd”自由提问。</p><select id="case"></select><div id="answer"></div></section>
<details class="panel"><summary>查看数据与分析方式</summary><div id="stats"></div><p>推荐来自有限买家评论，自动分析尚待复核。技术状态和完整来源都可在下方商品档案中展开查看。</p></details>
<section class="panel"><h2>继续挑选商品</h2><div class="controls"><input id="query" type="search" placeholder="搜索款式、关键词或商品编号"><select id="category"><option value="">全部品类</option><option value="tops">上衣</option><option value="bottoms">下装</option><option value="outerwear">外套</option><option value="all-body">连衣裙／连体装</option></select><input id="budget" type="number" min="1" placeholder="预算上限" style="width:155px"><label><input type="checkbox" id="est">按演示定价筛选全部商品</label></div><p id="count" class="muted"></p></section>
<div id="products"></div><div id="pager"></div>
'''

VIEW_JS=r'''
const products=DATA.products,assess=new Map(DATA.assessments.map(x=>[x.item_id,x])),reviews=new Map(DATA.reviews.map(x=>[x.review_key,x])),ann=new Map(DATA.annotations.map(x=>[x.annotation_key,x]));
const revBy=new Map();for(const r of reviews.values()){if(!revBy.has(r.item_id))revBy.set(r.item_id,[]);revBy.get(r.item_id).push(r);}
document.getElementById('priceNotice').textContent=DATA.presentation.global_price_notice+' 推荐理由参考买家评价，可以展开查看依据。';document.getElementById('est').checked=DATA.presentation.price_mode==='demo_catalog';
function priceText(p){return DATA.presentation.price_mode==='demo_catalog'?'¥'+p.price.toFixed(2):p.price_display;}
add(document.getElementById('stats'),'span',DATA.stats['商品数']+'件商品','pill');add(document.getElementById('stats'),'span',DATA.stats['评论数']+'条评论','pill');add(document.getElementById('stats'),'span',DATA.stats['自动或复核维度记录数']+'条维度证据','pill');add(document.getElementById('stats'),'span',DATA.stats['已提交复核评论数']+'条已导入复核','pill');
function evidenceBox(parent,key){const a=ann.get(key);if(!a)return;const r=reviews.get(a.review_key);const d=add(parent,'details');add(d,'summary',r.review_key+' · '+a.aspect_zh+' · '+({positive:'正向',negative:'反向',neutral:'描述',mixed:'褒贬混合'}[a.polarity]||a.polarity)+' · '+(a.certainty==='speculative'?'买家推测':'买家陈述'));add(d,'p',r.review_text);detail(d,'对应原文片段',a.evidence_text);detail(d,'原文与来源',r.original_text+'\n源文件：'+r.source_url+'\n数据行：'+r.source_line+'；CSV行：'+r.source_csv_row+'\n分析状态：'+a.human_review_status);}
const sel=document.getElementById('case');DATA.answers.forEach((a,i)=>{const o=el('option',a.query);o.value=i;sel.append(o);});
function showCase(){const a=DATA.answers[+sel.value],box=document.getElementById('answer');box.replaceChildren();add(box,'p',a.opening);for(const w of a.user_notices||[])add(box,'p',w,'muted');for(const r of a.recommendations){const c=add(box,'div',null,'card');add(c,'h3',r.title);const price=add(c,'p',r.price_display);price.style.fontSize='21px';price.style.fontWeight='bold';price.style.color='#285f64';const fit=add(c,'p',r.fit_assessment.summary);fit.style.fontWeight='bold';if(r.pros.length){add(c,'strong','优点');const list=add(c,'ul');for(const x of r.pros)add(list,'li',x);}if(r.cons.length){add(c,'strong','需要注意');const list=add(c,'ul');for(const x of r.cons)add(list,'li',x,'risk');}add(c,'p',r.purchase_advice);for(const x of r.user_notes||[])add(c,'p',x,'muted');}}
sel.onchange=showCase;showCase();
let page=0;const size=12;
function render(){const q=document.getElementById('query').value.trim().toLowerCase(),cat=document.getElementById('category').value,b=Number(document.getElementById('budget').value),est=document.getElementById('est').checked;const selected=products.filter(p=>(!cat||p.semantic_category===cat)&&(!b||((est||!p.price_is_estimated)&&p.price<=b))&&(!q||(p.title+' '+p.item_id+' '+(revBy.get(p.item_id)||[]).map(r=>r.review_text).join(' ')).toLowerCase().includes(q)));page=Math.min(page,Math.max(0,Math.ceil(selected.length/size)-1));document.getElementById('count').textContent='共'+selected.length+'件，按当前商品库显示价格筛选。';const box=document.getElementById('products');box.replaceChildren();for(const p of selected.slice(page*size,(page+1)*size)){const a=assess.get(p.item_id),c=add(box,'article',null,'card');add(c,'h3',p.title);add(c,'p',p.item_id,'muted');add(c,'span',priceText(p),'pill');add(c,'span',a.review_count+'条样本 · '+a.evidence_level_zh,'pill');detail(c,'评价与价格来源说明',p.price_note+'；原记录标记：'+p.price_display+'；自动分析待复核。');if(a.strengths.length)add(c,'p','有买家认可：'+a.strengths.map(x=>x.aspect_zh+'（'+x.review_count+'条）').join('、'));else add(c,'p','尚未识别到具体优点的充分证据。');if(a.risks.length)add(c,'p','也要留意：'+a.risks.map(x=>x.aspect_zh+'（'+x.review_count+'条）').join('、'),'risk');const d=add(c,'details');add(d,'summary','展开完整评论与证据');for(const r of revBy.get(p.item_id)||[]){const rd=add(d,'details');add(rd,'summary',r.review_key+' · 原评分'+r.rating+'/5');add(rd,'p',r.review_text);for(const e of DATA.annotations.filter(x=>x.review_key===r.review_key))evidenceBox(rd,e.annotation_key);if(!DATA.annotations.some(x=>x.review_key===r.review_key))add(rd,'p','自动规则未识别到具体维度，不代表评论中一定没有有效信息。','muted');}detail(c,'各维度计数',JSON.stringify(a.aspects,null,2));const link=add(c,'a','自行打开原始主图（将访问外部网站）');link.href=p.image_path;link.target='_blank';link.rel='noopener noreferrer';}const pager=document.getElementById('pager');pager.replaceChildren();const prev=add(pager,'button','上一页');prev.disabled=page===0;prev.onclick=()=>{page--;render();};add(pager,'span',(page+1)+' / '+Math.max(1,Math.ceil(selected.length/size)));const next=add(pager,'button','下一页');next.disabled=(page+1)*size>=selected.length;next.onclick=()=>{page++;render();};}
for(const id of ['query','category','budget','est'])document.getElementById(id).oninput=()=>{page=0;render();};render();
'''

ANN_BODY='''
<div class="notice">这是待复核的自动标签，不是正确答案。请对照原文检查否定、转折、证据范围和推测。仅修改实际有依据的标签；不明确的先标“需复核”。</div>
<section class="panel"><div class="controls"><button id="prev" class="secondary">上一条</button><select id="select"></select><button id="next" class="secondary">下一条</button><button id="export">下载已保存标注</button></div><p id="progress" class="muted"></p></section>
<section class="panel"><h2 id="title"></h2><p id="meta" class="muted"></p><div class="cols"><div><h3>来源原文</h3><pre id="original"></pre></div><div><h3>中文译文</h3><pre id="zh"></pre></div></div></section>
<section class="panel"><h2>核对观点</h2><p class="muted">逐条选择评价维度、态度和证据。证据请从上方原文或中文中复制，程序会检查是否对应。没有有效观点时可删除全部提案，再保存复核结果。</p><div id="labelForms"></div><button id="addLabel" class="secondary">添加一条观点</button><details><summary>高级：查看或编辑标签文件格式</summary><pre id="guide"></pre><textarea id="labels" spellcheck="false"></textarea><button id="applyJson" class="secondary">应用高级编辑</button></details><div class="controls"><input id="reviewer" placeholder="复核者代号，例如A"><button id="approve">保存为已复核</button><button id="pending" class="secondary">保存为需复核</button></div><p id="message"></p><p class="muted">进度尽可能保存在本浏览器；请及时下载JSONL，浏览器缓存不是正式备份。这里的保存不会修改源数据库，需要导入下载文件。</p></section>
'''

ANN_JS=r'''
const rows=DATA.rows,select=document.getElementById('select');const cacheKey='FITIN_ANNOTATION_'+DATA.version;let saved={};try{saved=JSON.parse(localStorage.getItem(cacheKey)||'{}');}catch(e){}rows.forEach((r,i)=>{const o=el('option',r.review_key+' · '+r.item_id);o.value=i;select.append(o);});document.getElementById('guide').textContent=JSON.stringify(DATA.guide,null,2);let current=0;
function msg(text,error=false){const m=document.getElementById('message');m.textContent=text;m.className=error?'error':'success';}
function compact(labels){return labels.map(x=>({aspect:x.aspect,polarity:x.polarity,feature:x.feature||'unspecified',certainty:x.certainty||'reported',source_language:x.source_language||'original',evidence_start:x.evidence_start,evidence_end:x.evidence_end,evidence_text:x.evidence_text}));}
const featureNames={soft:'柔软',comfortable:'舒适',breathable:'透气',non_itchy:'不扎肤',well_made:'做工',flattering:'修饰身形',true_size:'尺码合适',runs_small:'尺码偏小',runs_large:'尺码偏大',short_length:'长度偏短',long_length:'长度偏长',non_sheer:'不透',wash_well:'洗后表现好',no_shrink:'不缩水',no_fade:'不褪色',no_pilling:'不起球',durable:'耐用',color_true:'颜色一致',warm:'保暖',lightweight:'轻薄',thin:'薄',thick:'厚',boxy:'方形版型',general_like:'整体感受',unspecified:'未细分'};
let editing=[];
function syncJson(){document.getElementById('labels').value=JSON.stringify(editing,null,2);}
function dropdown(parent,label,options,value,onchange){const wrap=add(parent,'label',label+'：');const s=add(wrap,'select');for(const [k,v] of Object.entries(options)){const o=add(s,'option',v);o.value=k;}s.value=value;s.onchange=()=>{onchange(s.value);syncJson();};return s;}
function forms(){const box=document.getElementById('labelForms');box.replaceChildren();editing.forEach((l,i)=>{const card=add(box,'div',null,'card');const controls=add(card,'div',null,'controls');add(controls,'strong','观点'+(i+1));dropdown(controls,'维度',DATA.guide.aspects,l.aspect,v=>l.aspect=v);dropdown(controls,'态度',{positive:'正向',negative:'反向',neutral:'客观描述',mixed:'褒贬混合'},l.polarity,v=>l.polarity=v);dropdown(controls,'具体特征',featureNames,l.feature,v=>l.feature=v);dropdown(controls,'性质',{reported:'买家陈述的体验',speculative:'猜测、担心或希望'},l.certainty,v=>l.certainty=v);const remove=add(controls,'button','删除','secondary');remove.onclick=()=>{editing.splice(i,1);syncJson();forms();};const evidence=add(card,'textarea');evidence.style.minHeight='80px';evidence.value=l.evidence_text||'';evidence.placeholder='从上方原文或中文译文复制对应文字';const locate=()=>{const r=rows[current],t=l.source_language==='original'?r.original_text:r.review_text_zh,v=evidence.value;const old=Array.from(t).slice(l.evidence_start,l.evidence_end).join('');l.evidence_text=v;if(old!==v){const at=v?t.indexOf(v):-1;l.evidence_start=at<0?-1:Array.from(t.slice(0,at)).length;l.evidence_end=at<0?-1:l.evidence_start+Array.from(v).length;}syncJson();};dropdown(card,'证据来自',{original:'来源原文',zh_translation:'中文译文'},l.source_language,v=>{l.source_language=v;l.evidence_start=-1;l.evidence_end=-1;locate();});evidence.oninput=locate;add(card,'p','只复制实际支持该观点的文字；买家陈述也不等于已经独立核实的事实。','muted');});if(!editing.length)add(box,'p','当前没有观点标签。若核对后确实没有可用维度，可直接保存；否则点击添加。','muted');}
function show(){const r=rows[current],s=saved[r.review_key];select.value=current;document.getElementById('title').textContent=r.review_key+' · '+(current+1)+'/'+rows.length;document.getElementById('meta').textContent='商品：'+r.item_id+'；参考原评分：'+r.rating_for_reference_only+'；划分：'+r.split+'；状态：'+(s?s.status:'pending');document.getElementById('original').textContent=r.original_text;document.getElementById('zh').textContent=r.review_text_zh;editing=compact(s?s.labels:r.labels);syncJson();forms();if(s&&s.reviewed_by)document.getElementById('reviewer').value=s.reviewed_by;document.getElementById('progress').textContent='已保存'+Object.keys(saved).length+'条，其中已复核'+Object.values(saved).filter(x=>x.status==='approved').length+'条。请先完成小批共同标注，统一规则后再分工。';msg('');}
function save(status){try{const r=rows[current],labels=JSON.parse(document.getElementById('labels').value),reviewer=document.getElementById('reviewer').value.trim();if(!Array.isArray(labels))throw Error('标签必须是JSON列表');if(status==='approved'&&!reviewer)throw Error('请填写复核者代号');for(const l of labels){if(!Object.hasOwn(DATA.guide.aspects,l.aspect))throw Error('维度代码无效');if(!['positive','negative','neutral','mixed'].includes(l.polarity))throw Error('极性无效');if(!['reported','speculative'].includes(l.certainty))throw Error('证据性质无效');if(!['original','zh_translation'].includes(l.source_language))throw Error('证据语言无效');const t=l.source_language==='original'?r.original_text:r.review_text_zh;if(!Number.isInteger(l.evidence_start)||!Number.isInteger(l.evidence_end)||l.evidence_start<0||l.evidence_end<=l.evidence_start||l.evidence_end>Array.from(t).length)throw Error('证据位置无效');if(Array.from(t).slice(l.evidence_start,l.evidence_end).join('')!==l.evidence_text)throw Error('证据片段和字符位置不匹配');}saved[r.review_key]={review_key:r.review_key,item_id:r.item_id,source_sha256:r.source_sha256,status,reviewed_by:reviewer,labels,annotation_origin:'user_submitted',saved_at:new Date().toISOString()};try{localStorage.setItem(cacheKey,JSON.stringify(saved));}catch(e){msg('已暂存于本页内存，但浏览器不允许持久保存。请立即下载文件。',true);return;}show();msg('已保存；请下载文件保留。');}catch(e){msg(e.message,true);}}
select.onchange=()=>{current=+select.value;show();};document.getElementById('prev').onclick=()=>{current=Math.max(0,current-1);show();};document.getElementById('next').onclick=()=>{current=Math.min(rows.length-1,current+1);show();};document.getElementById('approve').onclick=()=>save('approved');document.getElementById('pending').onclick=()=>save('needs_review');document.getElementById('export').onclick=()=>download('FITIN_我的复核标注.jsonl',Object.values(saved).map(x=>JSON.stringify(x)).join('\n')+'\n');document.getElementById('addLabel').onclick=()=>{editing.push({aspect:'fabric_comfort',polarity:'neutral',feature:'unspecified',certainty:'reported',source_language:'original',evidence_start:-1,evidence_end:-1,evidence_text:''});syncJson();forms();};document.getElementById('applyJson').onclick=()=>{try{const v=JSON.parse(document.getElementById('labels').value);if(!Array.isArray(v))throw Error('需要JSON列表');editing=compact(v);syncJson();forms();msg('高级修改已载入，请核对后保存。');}catch(e){msg(e.message,true);}};show();
'''

def write_ui(out,products,reviews,assessments,annotations,pilot,answers,stats):
    from .analysis import ASPECTS
    out=Path(out)
    data={'presentation':json.loads((out/'展示与回答设置.json').read_text(encoding='utf-8')),'products':products,'reviews':reviews,'assessments':assessments,'annotations':annotations,'answers':answers,'stats':stats}
    (out/'离线查看器.html').write_text(html('FITIN 选衣助手',data,VIEW_BODY,VIEW_JS),encoding='utf-8')
    guide={'aspects':ASPECTS,'features':['soft','comfortable','breathable','non_itchy','well_made','flattering','true_size','runs_small','runs_large','short_length','long_length','non_sheer','wash_well','no_shrink','no_fade','no_pilling','durable','color_true','warm','lightweight','thin','thick','boxy','general_like','unspecified'],
        'rule':'保留原文实际支持的信息；描述不等于好坏，推测不当已发生。'}
    annotation_data={'rows':pilot,'version':stats['来源文件摘要']['reviews.csv'][:16],'guide':guide}
    (out/'标注工作台.html').write_text(html('FITIN 评论标注工作台',annotation_data,ANN_BODY,ANN_JS),encoding='utf-8')
    for name,target in [('打开离线查看器.cmd','离线查看器.html'),('打开标注工作台.cmd','标注工作台.html')]:
        (out/name).write_text('@echo off\nchcp 65001 >nul\nstart "" "%~dp0'+target+'"\n',encoding='utf-8')
    ps='''$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new()
$env:PYTHONIOENCODING = 'utf-8'
$entry = Join-Path $PSScriptRoot 'app/fitin_offline.py'
$bundled = Join-Path $env:USERPROFILE '.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe'
if (Test-Path -LiteralPath $bundled) { & $bundled $entry chat --data $PSScriptRoot }
elseif (Get-Command py -ErrorAction SilentlyContinue) { & py -3 $entry chat --data $PSScriptRoot }
elseif (Get-Command python -ErrorAction SilentlyContinue) { & python $entry chat --data $PSScriptRoot }
else { Write-Host '需要Python 3.10或以上。也可以直接打开离线查看器.html查看已生成结果。'; Read-Host '按回车结束' }
'''
    (out/'启动推荐问答.ps1').write_text(ps,encoding='utf-8-sig')
    (out/'启动推荐问答.cmd').write_text('@echo off\nchcp 65001 >nul\npowershell -NoProfile -ExecutionPolicy Bypass -File "%~dp0启动推荐问答.ps1"\npause\n',encoding='utf-8')
